window.DEX_DATA["sources:backport-64c07f801fc61ff4"]={"json":{"skins":[{"filename":"doctor.png"}],"names":[{"name":"医生"},{"name":"皮尔博士"},{"name":"史密斯博士"},{"name":"霍利迪博士"},{"name":"康复博士"}],"chat":[{"lines":[{"text":"伸出舌头，说啊——。"},{"text":"你的脸色有点苍白，需要补剂吗？"}]},{"lines":[{"text":"应该多晒晒太阳，对骨骼有好处。"},{"text":"下一位病人是你吗？今天真忙，唉。"}]},{"lines":[{"text":"我亲手做的药，味道可是最好的！"},{"text":"早知道该去学宝可梦医学，肯定更有趣。"}]},{"lines":[{"text":"记得一天喝两次补剂。也许三次，或者四次……"},{"text":"最好的补剂是笑声！你会讲笑话吗？"}]}]}};
